// fin-tv: stub for the type generated by upstream SwiftTerm's build plugin
// (SwiftTermBuildInfoPlugin). The vendored engine compiles as plain target
// sources, so the plugin never runs; Terminal.swift references these fields
// for the XTVERSION response only.
enum SwiftTermBuildInfo {
    static let tag = "v1.20.0"
    static let branch = "fin-vendored"
    static let version = "1.20.0"
}
